--
-- Name: fn_calculate_attraction_quality(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_calculate_attraction_quality(p_attraction_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_avg_rating NUMERIC(3,2) := 0;
    v_tickets_count INT := 0;
    v_reviews_count INT := 0;
    v_cancelled_count INT := 0;
    v_reports_count INT := 0;
    v_quality_score NUMERIC := 0;
BEGIN
    -- Check that the attraction exists
    IF NOT EXISTS (
        SELECT 1
        FROM attraction
        WHERE attraction_id = p_attraction_id
    ) THEN
        RAISE EXCEPTION 'Attraction with id % does not exist', p_attraction_id;
    END IF;

    -- Get average rating from the attraction table
    SELECT COALESCE(avg_rating, 0)
    INTO v_avg_rating
    FROM attraction
    WHERE attraction_id = p_attraction_id;

    -- Count tickets for this attraction
    SELECT COUNT(*)
    INTO v_tickets_count
    FROM ticket
    WHERE attraction_id = p_attraction_id;

    -- Count cancelled tickets for this attraction
    SELECT COUNT(*)
    INTO v_cancelled_count
    FROM ticket
    WHERE attraction_id = p_attraction_id
      AND LOWER(ticket_status) = 'cancelled';

    -- Count reviews for this attraction through tickets
    SELECT COUNT(*)
    INTO v_reviews_count
    FROM review r
    JOIN ticket t ON r.ticket_id = t.ticket_id
    WHERE t.attraction_id = p_attraction_id
      AND COALESCE(r.is_deleted, FALSE) = FALSE;

    -- Count reports on reviews of this attraction
    SELECT COUNT(*)
    INTO v_reports_count
    FROM reviewreport rr
    JOIN review r ON rr.review_id = r.review_id
    JOIN ticket t ON r.ticket_id = t.ticket_id
    WHERE t.attraction_id = p_attraction_id;

    /*
        Quality score logic:
        - Average rating is the main part: rating 1-5 becomes 20-100.
        - Tickets add popularity points, up to 20.
        - Reviews add reliability points, up to 15.
        - Cancelled tickets reduce score.
        - Reports reduce score.
    */
    v_quality_score :=
          (v_avg_rating * 20)
        + LEAST(v_tickets_count, 20)
        + LEAST(v_reviews_count, 15)
        - (v_cancelled_count * 2)
        - (v_reports_count * 3);

    -- Prevent negative score
    IF v_quality_score < 0 THEN
        v_quality_score := 0;
    END IF;

    RETURN ROUND(v_quality_score, 2);

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error in fn_calculate_attraction_quality: %', SQLERRM;
        RETURN 0;
END;
$$;


--
-- Name: fn_get_customer_activity_level(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_customer_activity_level(p_customer_id integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ticket_rec RECORD;

    v_total_tickets INT := 0;
    v_active_tickets INT := 0;
    v_used_tickets INT := 0;
    v_cancelled_tickets INT := 0;

    v_reviews_count INT := 0;
    v_reactions_count INT := 0;

    v_activity_level VARCHAR(30);
BEGIN
    -- Check that the customer exists
    IF NOT EXISTS (
        SELECT 1
        FROM customer
        WHERE customer_id = p_customer_id
    ) THEN
        RAISE EXCEPTION 'Customer with id % does not exist', p_customer_id;
    END IF;

    -- Implicit cursor:
    -- The FOR loop goes over all tickets of the customer.
    FOR v_ticket_rec IN
        SELECT ticket_id, ticket_status
        FROM ticket
        WHERE customer_id = p_customer_id
    LOOP
        v_total_tickets := v_total_tickets + 1;

        IF v_ticket_rec.ticket_status = 'active' THEN
            v_active_tickets := v_active_tickets + 1;

        ELSIF v_ticket_rec.ticket_status = 'used' THEN
            v_used_tickets := v_used_tickets + 1;

        ELSIF v_ticket_rec.ticket_status = 'cancelled' THEN
            v_cancelled_tickets := v_cancelled_tickets + 1;
        END IF;
    END LOOP;

    -- Count reviews written by this customer.
    -- In our schema, review is connected to customer through ticket.
    SELECT COUNT(*)
    INTO v_reviews_count
    FROM review r
    JOIN ticket t ON r.ticket_id = t.ticket_id
    WHERE t.customer_id = p_customer_id
      AND COALESCE(r.is_deleted, FALSE) = FALSE;

    -- Count reactions made by this customer
    SELECT COUNT(*)
    INTO v_reactions_count
    FROM reviewreaction
    WHERE customer_id = p_customer_id;

    -- Classify customer activity level
    IF v_total_tickets = 0
       AND v_reviews_count = 0
       AND v_reactions_count = 0 THEN

        v_activity_level := 'INACTIVE_CUSTOMER';

    ELSIF v_cancelled_tickets >= 5
          AND v_cancelled_tickets > (v_used_tickets + v_active_tickets) THEN

        v_activity_level := 'RISKY_CUSTOMER';

    ELSIF v_total_tickets >= 15
          AND v_used_tickets >= 8
          AND v_reviews_count >= 5
          AND v_reactions_count >= 10 THEN

        v_activity_level := 'VIP_CUSTOMER';

    ELSIF v_total_tickets >= 5
          OR v_reviews_count >= 3
          OR v_reactions_count >= 10 THEN

        v_activity_level := 'ACTIVE_CUSTOMER';

    ELSE
        v_activity_level := 'REGULAR_CUSTOMER';
    END IF;

    RETURN v_activity_level;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error in fn_get_customer_activity_level: %', SQLERRM;
        RETURN 'ERROR';
END;
$$;


--
-- Name: fn_trg_refresh_avg_rating_after_review_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_trg_refresh_avg_rating_after_review_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_attraction_id INT;
    v_old_attraction_id INT;
BEGIN
    -- Find attraction of NEW review
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        IF NEW.direct_attraction_id IS NOT NULL THEN
            v_new_attraction_id := NEW.direct_attraction_id;
        ELSIF NEW.ticket_id IS NOT NULL THEN
            SELECT attraction_id
            INTO v_new_attraction_id
            FROM ticket
            WHERE ticket_id = NEW.ticket_id;
        END IF;
    END IF;

    -- Find attraction of OLD review, relevant mainly for update
    IF TG_OP = 'UPDATE' THEN
        IF OLD.direct_attraction_id IS NOT NULL THEN
            v_old_attraction_id := OLD.direct_attraction_id;
        ELSIF OLD.ticket_id IS NOT NULL THEN
            SELECT attraction_id
            INTO v_old_attraction_id
            FROM ticket
            WHERE ticket_id = OLD.ticket_id;
        END IF;
    END IF;

    -- Refresh avg_rating for the new/current attraction
    IF v_new_attraction_id IS NOT NULL THEN
        UPDATE attraction a
        SET avg_rating = (
            SELECT COALESCE(ROUND(AVG(r.rating), 2), 0)
            FROM review r
            LEFT JOIN ticket t ON r.ticket_id = t.ticket_id
            WHERE COALESCE(r.is_deleted, FALSE) = FALSE
              AND (
                    t.attraction_id = v_new_attraction_id
                    OR r.direct_attraction_id = v_new_attraction_id
                  )
        )
        WHERE a.attraction_id = v_new_attraction_id;
    END IF;

    -- If the review moved from one attraction to another, refresh the old one too
    IF TG_OP = 'UPDATE'
       AND v_old_attraction_id IS NOT NULL
       AND v_old_attraction_id <> v_new_attraction_id THEN

        UPDATE attraction a
        SET avg_rating = (
            SELECT COALESCE(ROUND(AVG(r.rating), 2), 0)
            FROM review r
            LEFT JOIN ticket t ON r.ticket_id = t.ticket_id
            WHERE COALESCE(r.is_deleted, FALSE) = FALSE
              AND (
                    t.attraction_id = v_old_attraction_id
                    OR r.direct_attraction_id = v_old_attraction_id
                  )
        )
        WHERE a.attraction_id = v_old_attraction_id;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error in review avg_rating trigger: %', SQLERRM;
        RETURN NEW;
END;
$$;


--
-- Name: fn_trg_update_popularity_after_ticket_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_trg_update_popularity_after_ticket_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.ticket_status = 'active' THEN
        UPDATE attraction
        SET popularity_score = COALESCE(popularity_score, 0) + 1
        WHERE attraction_id = NEW.attraction_id;

    ELSIF NEW.ticket_status = 'used' THEN
        UPDATE attraction
        SET popularity_score = COALESCE(popularity_score, 0) + 2
        WHERE attraction_id = NEW.attraction_id;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error in ticket insert popularity trigger: %', SQLERRM;
        RETURN NEW;
END;
$$;


--
-- Name: pr_mark_problematic_attractions(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.pr_mark_problematic_attractions()
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_attraction_rec RECORD;

    v_avg_rating NUMERIC(10,2) := 0;
    v_reviews_count INT := 0;
    v_reports_count INT := 0;
    v_cancelled_tickets_count INT := 0;

    v_new_status VARCHAR(30);

    cur_attractions CURSOR FOR
        SELECT attraction_id, attraction_name, popularity_score
        FROM attraction
        ORDER BY attraction_id;
BEGIN
    OPEN cur_attractions;

    LOOP
        FETCH cur_attractions INTO v_attraction_rec;
        EXIT WHEN NOT FOUND;

        -- Calculate average rating and number of active reviews
        SELECT
            COALESCE(ROUND(AVG(r.rating), 2), 0),
            COUNT(r.review_id)
        INTO
            v_avg_rating,
            v_reviews_count
        FROM review r
        LEFT JOIN ticket t ON r.ticket_id = t.ticket_id
        WHERE COALESCE(r.is_deleted, FALSE) = FALSE
          AND (
                t.attraction_id = v_attraction_rec.attraction_id
                OR r.direct_attraction_id = v_attraction_rec.attraction_id
              );

        -- Count reports on reviews of this attraction
        SELECT COUNT(DISTINCT rep.report_id)
        INTO v_reports_count
        FROM reviewreport rep
        JOIN review r ON rep.review_id = r.review_id
        LEFT JOIN ticket t ON r.ticket_id = t.ticket_id
        WHERE
            t.attraction_id = v_attraction_rec.attraction_id
            OR r.direct_attraction_id = v_attraction_rec.attraction_id;

        -- Count cancelled tickets
        SELECT COUNT(*)
        INTO v_cancelled_tickets_count
        FROM ticket
        WHERE attraction_id = v_attraction_rec.attraction_id
          AND ticket_status = 'cancelled';

        -- Business logic for status
        IF v_reports_count >= 10 OR v_cancelled_tickets_count >= 20 THEN
            v_new_status := 'NEEDS_REVIEW';

        ELSIF v_reviews_count >= 5 AND v_avg_rating < 3 THEN
            v_new_status := 'LOW_RATED';

        ELSIF v_attraction_rec.popularity_score >= 50 AND v_avg_rating >= 3.5 THEN
            v_new_status := 'POPULAR';

        ELSE
            v_new_status := 'ACTIVE';
        END IF;

        -- DML update
        UPDATE attraction
        SET attraction_status = v_new_status
        WHERE attraction_id = v_attraction_rec.attraction_id;

        RAISE NOTICE 'Attraction % status updated to %',
            v_attraction_rec.attraction_id,
            v_new_status;
    END LOOP;

    CLOSE cur_attractions;

EXCEPTION
    WHEN OTHERS THEN
        IF cur_attractions%ISOPEN THEN
            CLOSE cur_attractions;
        END IF;

        RAISE NOTICE 'Error in pr_mark_problematic_attractions: %', SQLERRM;
END;
$$;


--
-- Name: pr_refresh_attraction_popularity(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.pr_refresh_attraction_popularity()
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_attraction_rec RECORD;

    v_active_tickets_count INT := 0;
    v_used_tickets_count INT := 0;
    v_cancelled_tickets_count INT := 0;
    v_group_tickets_count INT := 0;

    v_new_popularity_score INT := 0;

    cur_attractions CURSOR FOR
        SELECT attraction_id, attraction_name
        FROM attraction
        ORDER BY attraction_id;
BEGIN
    OPEN cur_attractions;

    LOOP
        FETCH cur_attractions INTO v_attraction_rec;
        EXIT WHEN NOT FOUND;

        -- Count regular tickets by status
        SELECT COUNT(*)
        INTO v_active_tickets_count
        FROM ticket
        WHERE attraction_id = v_attraction_rec.attraction_id
          AND ticket_status = 'active';

        SELECT COUNT(*)
        INTO v_used_tickets_count
        FROM ticket
        WHERE attraction_id = v_attraction_rec.attraction_id
          AND ticket_status = 'used';

        SELECT COUNT(*)
        INTO v_cancelled_tickets_count
        FROM ticket
        WHERE attraction_id = v_attraction_rec.attraction_id
          AND ticket_status = 'cancelled';

        -- Count group booking tickets only if booking_details exists
        IF to_regclass('booking_details') IS NOT NULL THEN
            EXECUTE
                'SELECT COALESCE(SUM(ticket_count), 0)
                 FROM booking_details
                 WHERE attraction_id = $1'
            INTO v_group_tickets_count
            USING v_attraction_rec.attraction_id;
        ELSE
            v_group_tickets_count := 0;
        END IF;

        -- Calculate score
        v_new_popularity_score :=
            GREATEST(
                  v_active_tickets_count
                + (v_used_tickets_count * 2)
                + v_group_tickets_count
                - v_cancelled_tickets_count,
                0
            );

        -- DML update
        UPDATE attraction
        SET popularity_score = v_new_popularity_score
        WHERE attraction_id = v_attraction_rec.attraction_id;

        RAISE NOTICE 'Attraction % updated with popularity_score = %',
            v_attraction_rec.attraction_id,
            v_new_popularity_score;
    END LOOP;

    CLOSE cur_attractions;

EXCEPTION
    WHEN OTHERS THEN
        IF cur_attractions%ISOPEN THEN
            CLOSE cur_attractions;
        END IF;

        RAISE NOTICE 'Error in pr_refresh_attraction_popularity: %', SQLERRM;
END;
$_$;


