--
-- Name: attraction; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attraction (
    attraction_id integer NOT NULL,
    attraction_name character varying(100) NOT NULL,
    city character varying(50) NOT NULL,
    category character varying(50),
    description character varying(255),
    category_id integer,
    location character varying(255),
    price_per_person numeric(10,2),
    duration_hours integer,
    target_audience character varying(100),
    avg_rating numeric(3,2),
    main_image_url character varying(255),
    difficulty_id integer,
    popularity_score integer DEFAULT 0,
    attraction_status character varying(30) DEFAULT 'ACTIVE'::character varying,
    CONSTRAINT chk_attraction_status CHECK (((attraction_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'POPULAR'::character varying, 'NEEDS_REVIEW'::character varying, 'LOW_RATED'::character varying])::text[])))
);


