    CONSTRAINT ticket_price_check CHECK ((price > (0)::numeric))
);


--
-- Name: view_attraction_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_attraction_overview AS
 SELECT a.attraction_id,
    a.attraction_name,
    a.city,
    a.category,
    cat.name AS category_name,
    dl.name AS difficulty_level,
    a.avg_rating AS stored_avg_rating,
    count(DISTINCT t.ticket_id) AS individual_tickets_sold,
    count(DISTINCT bd.booking_id) AS group_bookings_count,
    count(DISTINCT
        CASE
            WHEN (r.ticket_id IS NOT NULL) THEN r.review_id
            ELSE NULL::integer
        END) AS ticket_reviews_count,
    count(DISTINCT
        CASE
            WHEN (r.direct_attraction_id IS NOT NULL) THEN r.review_id
            ELSE NULL::integer
        END) AS direct_reviews_count,
    count(DISTINCT r.review_id) AS total_reviews,
    round(avg(r.rating), 2) AS calculated_avg_rating
   FROM (((((public.attraction a
     LEFT JOIN public.category cat ON ((a.category_id = cat.category_id)))
     LEFT JOIN public.difficulty_level dl ON ((a.difficulty_id = dl.difficulty_id)))
     LEFT JOIN public.ticket t ON ((a.attraction_id = t.attraction_id)))
     LEFT JOIN public.booking_details bd ON ((a.attraction_id = bd.attraction_id)))
     LEFT JOIN public.review r ON (((r.ticket_id = t.ticket_id) OR (r.direct_attraction_id = a.attraction_id))))
  GROUP BY a.attraction_id, a.attraction_name, a.city, a.category, cat.name, dl.name, a.avg_rating;


--
-- Name: view_booking_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_booking_summary AS
 SELECT b.booking_id,
    b.booking_date,
    b.status AS booking_status,
    b.total_ticket_count,
    b.contact_name,
    b.contact_email,
    c.customer_id,
    c.full_name AS customer_name,
    a.attraction_id,
    a.attraction_name,
    a.city AS attraction_location,
    a.avg_rating,
    dl.name AS difficulty_level,
    cat.name AS category_name,
    bd.ticket_count AS tickets_for_this_attraction,
    a.price_per_person,
    ((bd.ticket_count)::numeric * a.price_per_person) AS subtotal
   FROM (((((public.booking b
     JOIN public.customer c ON ((b.customer_id = c.customer_id)))
     JOIN public.booking_details bd ON ((b.booking_id = bd.booking_id)))
     JOIN public.attraction a ON ((bd.attraction_id = a.attraction_id)))
     LEFT JOIN public.difficulty_level dl ON ((a.difficulty_id = dl.difficulty_id)))
     LEFT JOIN public.category cat ON ((a.category_id = cat.category_id)));


--
-- Name: view_review_details; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_review_details AS
 SELECT r.review_id,
    r.rating,
    r.title,
    r.content,
    r.review_date,
    r.is_deleted,
    c.customer_id,
    c.full_name AS customer_name,
    c.email AS customer_email,
    a.attraction_id,
    a.attraction_name,
    a.city,
    a.category,
    t.ticket_id,
    t.visit_date,
    count(rr.reaction_id) FILTER (WHERE ((rr.reaction_type)::text = 'like'::text)) AS likes_count,
    count(rr.reaction_id) FILTER (WHERE ((rr.reaction_type)::text = 'dislike'::text)) AS dislikes_count,
    count(DISTINCT rep.report_id) AS reports_count
   FROM (((((public.review r
     JOIN public.ticket t ON ((r.ticket_id = t.ticket_id)))
     JOIN public.customer c ON ((t.customer_id = c.customer_id)))
     JOIN public.attraction a ON ((t.attraction_id = a.attraction_id)))
     LEFT JOIN public.reviewreaction rr ON ((r.review_id = rr.review_id)))
     LEFT JOIN public.reviewreport rep ON ((r.review_id = rep.review_id)))
  WHERE (r.ticket_id IS NOT NULL)
  GROUP BY r.review_id, r.rating, r.title, r.content, r.review_date, r.is_deleted, c.customer_id, c.full_name, c.email, a.attraction_id, a.attraction_name, a.city, a.category, t.ticket_id, t.visit_date;


